import 'package:flutter/material.dart';
import 'package:uuid/uuid.dart';
import '../../core/database/app_database.dart';
import '../defects/defects_page.dart';
class InspectionsPage extends StatefulWidget{const InspectionsPage({super.key});@override State<InspectionsPage> createState()=>_InspectionsPageState();}
class _InspectionsPageState extends State<InspectionsPage>{List<Map<String,dynamic>> rows=[],buildings=[];@override void initState(){super.initState();load();}Future<void> load()async{rows=await AppDatabase.instance.query('inspections',order:'date DESC');buildings=await AppDatabase.instance.query('buildings');if(mounted)setState((){});}Future<void> start()async{if(buildings.isEmpty){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('أضف مبنى أولًا')));return;}String bid=buildings.first['id'];final e=TextEditingController();final ok=await showDialog<bool>(context:context,builder:(c)=>StatefulBuilder(builder:(c,set)=>AlertDialog(title:const Text('بدء معاينة'),content:Column(mainAxisSize:MainAxisSize.min,children:[DropdownButtonFormField(value:bid,items:buildings.map((b)=>DropdownMenuItem(value:b['id'],child:Text(b['name']))).toList(),onChanged:(v)=>set(()=>bid=v!)),TextField(controller:e,decoration:const InputDecoration(labelText:'اسم المهندس'))]),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('إلغاء')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('بدء'))])));if(ok==true&&e.text.isNotEmpty){await AppDatabase.instance.insert('inspections',{'id':const Uuid().v4(),'buildingId':bid,'engineer':e.text,'date':DateTime.now().toIso8601String(),'status':'نشطة','notes':''});load();}}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('المعاينات')),floatingActionButton:FloatingActionButton.extended(onPressed:start,icon:const Icon(Icons.play_arrow),label:const Text('بدء')),body:ListView(padding:const EdgeInsets.all(16),children:rows.map((x)=>Card(child:ListTile(title:Text('معاينة ${x['date'].toString().substring(0,10)}'),subtitle:Text('المهندس: ${x['engineer']}'),onTap:()=>Navigator.push(c,MaterialPageRoute(builder:(_)=>DefectsPage(inspection:x))))).toList()));}
class BuildingInspectionPage extends StatelessWidget{final Map<String,dynamic> building;const BuildingInspectionPage({super.key,required this.building});@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(building['name'])),body:const Center(child:Text('يمكن بدء معاينة هذا المبنى من تبويب المعاينة الميدانية.')));}
